package com.acme.shop;

import java.util.List;

public class OrderService {
    public long total(List<LineItem> items) {
        long subtotal = 0;
        for (LineItem item : items) {
            subtotal += item.price() * item.quantity();
        }
        return subtotal + shipping(subtotal);
    }

    public String receipt(List<LineItem> items) {
        return "Total: " + formatCents(total(items));
    }

    private long shipping(long subtotal) {
        return subtotal >= 5000 ? 0 : 499;
    }

    static String formatCents(long cents) {
        return String.format("%d.%02d", cents / 100, cents % 100);
    }
}

